<?php require_once '../config/config.php';
if(!empty($_SESSION['admin_id'])){ header('Location: index.php'); exit; }
$msg='';
try{$count=(int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn();}catch(Throwable $e){$count=-1;}
if($_SERVER['REQUEST_METHOD']==='POST' && $count===0){$name=trim($_POST['name']);$email=trim($_POST['email']);$pass=$_POST['password']; if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pass)>=8){$s=db()->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$msg='Compte créé. Vous pouvez vous connecter.';$count=1;}else{$msg='Vérifiez les champs et utilisez un mot de passe d’au moins 8 caractères.';}}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configuration admin</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="auth"><div class="card"><span class="eyebrow">PREMIÈRE INSTALLATION</span><h1>Créer l’administrateur</h1><?php if($count!==0):?><p>Le compte administrateur existe déjà. <a href="index.php">Se connecter</a>.</p><?php else:?><form method="post"><label>Nom<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Mot de passe<input type="password" name="password" minlength="8" required></label><button class="btn" type="submit">Créer le compte</button></form><?php endif;?><?php if($msg):?><p class="notice"><?=e($msg)?></p><?php endif;?></div></main></body></html>
